import unittest

from solution import triangular_total


class TriangularTotalTests(unittest.TestCase):
    def test_boundary_zero(self):
        self.assertEqual(triangular_total(0), 0)

    def test_one(self):
        self.assertEqual(triangular_total(1), 1)

    def test_normal_values(self):
        self.assertEqual(triangular_total(5), 15)
        self.assertEqual(triangular_total(10), 55)

    def test_negative_integer(self):
        with self.assertRaises(ValueError):
            triangular_total(-1)

    def test_rejects_boolean_and_other_types(self):
        for value in (True, False, 1.0, "3", None, []):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    triangular_total(value)


if __name__ == "__main__":
    unittest.main()

